//! RFC 1002 §4.3.1: the NetBIOS session service prefixes each message over TCP
//! port 139 with a one-octet type, a one-octet flags field whose low bit extends
//! the length, and a 16-bit length. Type 0 is a session message, which over port
//! 139 carries SMB.
//!
//! Generated by dev/protogen from dev/protogen/specs/nbtsession.toml. Field layouts
//! come from the RFC cited above; edit the spec, not this file.

use crate::field::FieldDesc;
use crate::proto::{Next, ProtoDesc, ProtoId};

// protogen:hand begin
/// RFC 1002 §4.3.1: the low bit of the flags octet is the length's high bit.
fn message_len(hdr: &[u8]) -> usize {
    match hdr.get(0..4) {
        Some(b) => (((b[1] & 1) as usize) << 16) | u16::from_be_bytes([b[2], b[3]]) as usize,
        None => 0,
    }
}

fn content_len(hdr: &[u8]) -> usize {
    4 + message_len(hdr)
}

fn next(hdr: &[u8]) -> Next {
    if hdr.first() == Some(&0) && hdr.get(4..8) == Some(&[0xfe, b'S', b'M', b'B'][..]) {
        return Next::Proto(ProtoId::Smb2);
    }
    Next::Raw
}

/// §4.3.2 onwards: the six session packet types.
pub fn looks_like(p: &[u8]) -> bool {
    p.len() >= 4 && matches!(p[0], 0x00 | 0x81 | 0x82 | 0x83 | 0x84 | 0x85)
}
