#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// RFC 1002 §4.3.1 session message of four octets.
    fn vector() -> Vec<u8> {
        vec![0x00, 0x00, 0x00, 0x04, 0xff, 0x53, 0x4d, 0x42]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::NbtSession);
        let l = p.find_layer(ProtoId::NbtSession).unwrap();
        assert_eq!(p.get(l, "TYPE").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "FLAGS").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "LENGTH").unwrap(), FieldValue::Uint(4));
        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::NbtSession);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::NbtSession);
        let l = p.find_layer(ProtoId::NbtSession).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::NbtSession, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
